import { defineConfig, devices } from "@playwright/test";

/** Shared browser setup for every project (see the projects comment below). */
const CHROMIUM = {
  ...devices["Desktop Chrome"],
  channel: "chromium",
  launchOptions: {
    args: ["--disable-background-timer-throttling", "--disable-backgrounding-occluded-windows", "--disable-renderer-backgrounding"]
  }
};

/**
 * E2E smoke tests run against the production build (next start) — the dev
 * server's React StrictMode double-mounts the game engine and would make
 * runs slower and noisier.
 *
 * Files are named *.e2e.ts (NOT *.test.ts / *.spec.ts) so `bun test` does not
 * try to execute them with its own runner.
 */
export default defineConfig({
  testDir: "e2e",
  testMatch: "**/*.e2e.ts",
  // Two workers, file-level parallelism only (fullyParallel stays false): a
  // parallel-safety audit cleared every spec file for concurrent execution —
  // distinct signup-email prefixes per file, account-scoped /api/worlds, only
  // two room-consuming files against the game server's room cap, per-context
  // storage/service worker, no cross-file ordering. New spec files must keep
  // those invariants (see docs/testing.md).
  fullyParallel: false,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 2 : 0,
  workers: 2,
  // The list reporter runs on CI too: the github reporter records no per-spec
  // durations, which makes slow-suite diagnosis needlessly blind.
  reporter: process.env.CI ? [["github"], ["list"], ["html", { open: "never" }]] : "list",
  timeout: 60000,
  use: {
    baseURL: "http://localhost:3000",
    // Trace only from the first retry: continuous recording taxes the CPU-bound
    // CI runner on every green first attempt (and failed heavy specs produced
    // 600+ MB artifacts); a retry is exactly when a trace is worth its cost.
    trace: "on-first-retry"
  },
  // channel "chromium" runs the full browser in new-headless mode: the default
  // headless shell rejects requestPointerLock (WrongDocumentError).
  //
  // The no-throttling args are load-bearing for the two-browser multiplayer
  // specs: they assert on a "witness" page's replica while the other page
  // holds focus (bringToFront), and Chromium throttles rAF in backgrounded/
  // occluded pages — a throttled witness stops applying server ticks, so
  // confirmations that pass in seconds locally starve on the CI runner.
  //
  // Three CHAINED projects so the two heavy two-browser specs never overlap —
  // each runs two live software-GL game pages, and four at once starve the
  // rAF-driven client streams (mining, poses, predictions) into flaking even
  // on a fast machine. The light majority still gets both workers; each heavy
  // spec then runs on an otherwise idle machine. To run one heavy spec alone
  // without its dependency chain: `bunx playwright test <file> --no-deps`.
  projects: [
    {
      name: "light",
      testIgnore: ["**/multiplayer.e2e.ts", "**/nether-online.e2e.ts"],
      use: CHROMIUM
    },
    {
      name: "heavy-multiplayer",
      testMatch: "**/multiplayer.e2e.ts",
      dependencies: ["light"],
      use: CHROMIUM
    },
    {
      name: "heavy-nether",
      testMatch: "**/nether-online.e2e.ts",
      dependencies: ["heavy-multiplayer"],
      use: CHROMIUM
    }
  ],
  webServer: [
    {
      // The web app with a full online stack and ZERO external services: an
      // ephemeral in-process Postgres (pglite://) backs accounts/worlds, and
      // the game server below is where its join tickets point.
      command: "bun run build && bun run start",
      url: "http://localhost:3000",
      reuseExistingServer: !process.env.CI,
      timeout: 180000,
      env: {
        DATABASE_URL: "pglite://memory",
        BETTER_AUTH_SECRET: "e2e-secret-e2e-secret-e2e-secret",
        BETTER_AUTH_URL: "http://localhost:3000",
        GAME_TICKET_SECRET: "e2e-ticket-secret",
        NEXT_PUBLIC_GAME_SERVER_URL: "ws://localhost:18080"
      }
    },
    {
      // The game server, database-free (rooms persist in memory for the run).
      command: "bun server/index.ts",
      url: "http://localhost:18080/health",
      reuseExistingServer: !process.env.CI,
      timeout: 60000,
      env: {
        PORT: "18080",
        PERSISTENCE: "memory",
        GAME_TICKET_SECRET: "e2e-ticket-secret",
        // Headroom over the default 6: with two workers, both room-consuming
        // spec files can hold a live room at once, and CI retries can pile
        // idle rooms for up to the 5-minute eviction window.
        MAX_ROOMS: "8"
      }
    }
  ]
});

// ── a block edit crosses the wire ─────────────────────────────────────────
// The host digs straight down. The host's own journal entry may be its
// PREDICTED break (replica mining commits locally now), so the proof that
// the server decided and broadcast it is the FRIEND's journal changing.
await forceDigStraightDown(host);
await host.waitForTimeout(1000); // settle (slow CI renderers need the margin)
await host.mouse.down();
for (const page of [host, friend]) {
  // 45s: the friend's copy arrives over the wire, and a slammed runner (the
  // Bun game server shares the box) has lagged that hop past 30s.
  await expect.poll(() => page.evaluate(() => window.__monecraft!.engine.state.blockChanges.changes().length), { timeout: 45000 }).toBeGreaterThan(0);
}
await host.mouse.up();

// ── chat round-trips, rendering in the other player's log ────────────────
// 30s like the block-edit poll: a slammed CI runner has been seen lagging
// the second page's connection by tens of seconds (10s flaked in CI).
await host.evaluate(() => window.__monecraft!.net!.sendChat("hello from the host"));
await expect(friend.getByText("hello from the host")).toBeVisible({ timeout: 30000 });
await friend.evaluate(() => window.__monecraft!.net!.sendChat("hi back"));
await expect(host.getByText("hi back")).toBeVisible({ timeout: 30000 });

// ── the roster lists both players; only the owner (host) gets a Kick control ─
for (const page of [host, friend]) {
  expect(await page.evaluate(() => window.__monecraft!.net!.roster().length)).toBe(2);
}
await expect(host.getByRole("button", { name: /^Kick / })).toBeVisible(); // owner sees it
expect(await friend.getByRole("button", { name: /^Kick / }).count()).toBe(0); // a member does not

// (Arrow replication — the `prj` channel — is covered by unit tests rather than
// here: driving it end-to-end means creative-mode + inventory juggling + firing
// into open sky to dodge the first-tick despawn, too fragile for a reliable e2e.
// See server/room.test.ts (broadcast) and NetworkSession.test.ts (upsert).)

// ── the friend's own break under latency: local-first, and still propagates ──
// 400±100 ms simulated one-way (~800 ms RTT): the friend digs; the block must
// vanish from the friend's OWN world (its replica commits the break locally,
// ahead of the server), AND the edit must still reach the host over the
// lagged link. That the local commit rides the PREDICTION ledger (a pending
// entry held until the server confirms) is pinned in NetworkSession.test.ts —
// that ledger window is a sub-second internal transient, too narrow to
// observe reliably from a cross-process e2e poll, so here we assert the
// user-visible journey rather than the ledger's internals.
//
// Foreground the friend first: unlike RECEIVING the host's edit (network
// callbacks fire while occluded), the friend's OWN break is engine-rAF-driven,
// and the browser throttles rAF hard on a backgrounded page (the friend has
// sat behind the host all along), so occluded its mining crawls and can miss
// the 45s window. Foregrounded, its engine steps at full rate. (bringToFront
// alone once looked like it broke digging — that was the airborne-aim miss the
// onGround wait in forceDigStraightDown now covers, not bringToFront itself.)

