4	/**
5	 * Nether travel in an ONLINE world, end-to-end through the real stack: the
6	 * host builds and ignites a portal with real networked placeBlock commands
7	 * (every obsidian cell is confirmed by the server's journal echo), dwells,
8	 * and the server hands them to a lazily-born nether shard — the client swaps
9	 * its replica and renderer around the SAME live socket. The friend watches
10	 * the roster tag flip, follows through, both meet in the nether, and the
11	 * host rides the arrival portal home. Creative keeps the build free and
12	 * hostiles passive; the terrain is REAL (the memory-persistence game server
13	 * auto-creates default-type worlds whatever the create form says), so the
14	 * build anchors on a scanned level site rather than assumed-flat ground.
15	 */
16	
17	/** Aims the replica player's eye ray at a world point (yaw/pitch convention from lookDirection). */
18	async function aimAt(page: Page, target: { x: number; y: number; z: number }): Promise<void> {
19	  await page.evaluate((t) => {
20	    const s = window.__monecraft!.engine.state;
21	    const eye = { x: s.player.position.x, y: s.player.position.y + 1.62, z: s.player.position.z };
22	    const dx = t.x - eye.x;
23	    const dy = t.y - eye.y;
24	    const dz = t.z - eye.z;
25	    const len = Math.hypot(dx, dy, dz);
26	    s.player.pitch = Math.asin(dy / len);
27	    s.player.yaw = Math.atan2(-dx, -dz);
28	  }, target);
29	}
30	
31	/**
32	 * Moves the (flying) player in ≤1-block hops. The 20 Hz pose stream keeps
33	 * `elapsed` at one tick server-side, so each pose may move at most
34	 * ~FLY_SPEED×1.6×0.05+0.5 ≈ 1.3 blocks — a bigger hop is refused and
35	 * force-posed back, which is exactly the stall this helper must avoid.
36	 */
37	async function flyTo(page: Page, target: { x: number; y: number; z: number }, stepSize = 1, ignoreY = false): Promise<void> {
38	  let lastDist = Infinity;
39	  let stalled = 0;
40	  for (let hop = 0; hop < 400; hop += 1) {
41	    const dist = await page.evaluate(
42	      ({ t, stepSize: size, ignoreY: flat }) => {
43	        const p = window.__monecraft!.engine.state.player;
44	        const dx = t.x - p.position.x;
45	        const dy = flat ? 0 : t.y - p.position.y;
46	        const dz = t.z - p.position.z;
47	        const d = Math.hypot(dx, dy, dz);
48	        if (d < 0.3) return 0;
49	        const step = Math.min(size, d);
50	        p.position.set(p.position.x + (dx / d) * step, p.position.y + (dy / d) * step, p.position.z + (dz / d) * step);
51	        p.velocity.set(0, 0, 0);
52	        return d;
53	      },
54	      { t: target, stepSize, ignoreY }
55	    );
56	    if (dist === 0) return;
57	    // Collision stall (a canopy or ledge the site scan couldn't see): the
58	    // physics keeps pushing the hop back. Dodge up-and-sideways and re-run —
59	    // the straight line re-forms from the new spot.
60	    stalled = lastDist - dist < 0.05 ? stalled + 1 : 0;
61	    lastDist = dist;
62	    if (stalled >= 5) {
63	      stalled = 0;
64	      lastDist = Infinity;
65	      await page.evaluate((h) => {
66	        const p = window.__monecraft!.engine.state.player;
67	        p.position.set(p.position.x + (h % 2 === 0 ? 0.8 : -0.8), p.position.y + 1.5, p.position.z);
68	        p.velocity.set(0, 0, 0);
69	      }, hop);
70	    }
71	    await page.waitForTimeout(120); // let the pose stream carry the hop
72	  }
73	  const debug = await page.evaluate(() => {
74	    const s = window.__monecraft!.engine.state;
75	    const p = s.player;
76	    const cell = { x: Math.floor(p.position.x), y: Math.floor(p.position.y), z: Math.floor(p.position.z) };
77	    return {
78	      pos: { x: p.position.x, y: p.position.y, z: p.position.z },
79	      isFlying: p.isFlying,
80	      dimension: s.dimension,
81	      status: window.__monecraft!.net?.status(),
82	      blockAt: s.world.get(cell.x, cell.y, cell.z),
83	      blockBelow: s.world.get(cell.x, cell.y - 1, cell.z)
84	    };
85	  });
86	  throw new Error(`could not reach ${JSON.stringify(target)}; player=${JSON.stringify(debug)}`);
87	}
88	
89	/**
90	 * Ground movement: sub-clamp steps (a NON-flying player's per-pose allowance
91	 * is under a block at the 20 Hz cadence) on the XZ plane only — gravity owns
92	 * y, and chasing a captured y that physics has since settled away from would
93	 * stall forever against the ground.
94	 */
95	const walkTo = (page: Page, target: { x: number; y: number; z: number }) => flyTo(page, target, 0.8, true);
96	
97	/**
98	 * Waits until the WITNESS's replica shows the placer at the placer's own local
99	 * pose — proof the pose has round-tripped placer → server → witness, so the
100	 * server's next command raycast runs from the very aim the script computed.
101	 * A blind post-aim sleep is NOT enough on a loaded CI runner: the 20 Hz pose
102	 * stream can lag the scripted aim by whole seconds, and the server then
103	 * raycasts with a STALE look direction and places (or refuses) elsewhere —
104	 * the exact flake that shipped three red main runs. Tolerances sit well above
105	 * the wire quantization (2 decimals position, 3 decimals angles); yaw compares
106	 * wrap-aware. The witness renders remotes 125–450 ms in the past, which the
107	 * poll simply rides out.
108	 */
109	async function poseSettled(placer: Page, witness: Page): Promise<void> {
110	  const want = await placer.evaluate(() => {
