119	          // With exactly two players, "the other one" is the placer — no id plumbing.
120	          const remote = [...s.players.values()].find((p) => p !== s.player);
121	          if (!remote) return Number.POSITIVE_INFINITY;
122	          const wrap = (a: number, b: number) => Math.abs(Math.atan2(Math.sin(a - b), Math.cos(a - b)));
