      onGround: p.onGround,
      pitch: +p.pitch.toFixed(2),
      yaw: +p.yaw.toFixed(2),
      mineHeld: window.__monecraft!.input.input.mineHeld,
      pointerLocked: window.__monecraft!.input.pointerLocked,
      feet: s.world.get(fx, fy, fz),
