85	  getBiome(x: number, z: number): BiomeId {
86	    // Two incommensurate, direction-rotated sine octaves per field, with
87	    // dominant wavelengths of ~250-900 blocks: each field traverses several
88	    // cycles across the 512-block map, so every world gets coherent patches
89	    // of all five biomes (~60-150 block scale).
90	    // portableSin (not Math.sin): the biome field feeds terrain generation, so
91	    // it must be bit-identical across JS engines — see lib/world/noise.ts.
92	    const s = this.seed * 0.007;
93	    const temp = portableSin(x * 0.013 + z * 0.006 + s * 1.3) * 0.6 + portableSin(x * 0.029 - z * 0.017 + s * 2.4) * 0.4;
94	    const moisture = portableSin(x * 0.007 - z * 0.012 + s * 0.8) * 0.6 + portableSin(x * 0.019 + z * 0.023 - s * 1.6) * 0.4;
